// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, bytes memory data, uint256 fundAmount, uint256 commandValue) public {
        // Bound fundAmount to a reasonable range and ensure it's > 0
        fundAmount = bound(fundAmount, 1, 100 ether);
        commandValue = bound(commandValue, 0, 10 ether);

        // Fund the contract via the multiplicate function (which sends Ether to someone else but we capture the deposit first)
        // We need to call multiplicate with a high msg.value that executes the if-block
        // To make the condition true in reference (msg.value >= balance), we first ensure balance is 0 by funding
        // Actually, we'll just send Ether directly to the contract via receive() to set a baseline
        vm.deal(address(c), 1 ether);

        // Record initial balance of the contract
        uint256 initialBalance = address(c).balance;

        // Call multiplicate with msg.value = fundAmount (this will increase the contract's balance temporarily)
        (bool success,) = address(c).call{value: fundAmount}(abi.encodeWithSignature("multiplicate(address)", adr));
        assertTrue(success);

        // Record balance after multiplicate call (should have increased by fundAmount in reference, but in bug it may not)
        uint256 balanceAfterMultiplicate = address(c).balance;

        // Now call Command with a value
        (bool commandSuccess,) = address(c).call{value: commandValue}(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        assertTrue(commandSuccess);

        // Final balance
        uint256 finalBalance = address(c).balance;

        // The rule: The contract's balance should never decrease below the initialBalance (in reference, multiplicate drains all funds plus msg.value, so balance after multiplicate is at least initialBalance)
        // Actually, let's rethink: In reference, multiplicate sends balance+msg.value to adr, so it drains the contract. In bug, multiplicate only triggers when msg.value <= balance, so it may not drain.
        // We need a rule that distinguishes the two.
        // Instead, let's track that after calling Command, the balance should be at least 1 wei if we've never called multiplicate with sufficient funds.
        // Better: In reference, multiplicate only executes when msg.value >= balance, which means after execution, balance becomes 0. In bug, it executes when msg.value <= balance, so after execution, balance becomes (balance + msg.value) which is >= original balance, actually it sends (balance+msg.value) to adr, so balance becomes 0 after execution too? No, multiplicate transfers balance+msg.value, not balance.
        // Wait, multiplicate does: payable(adr).transfer(address(this).balance+msg.value); This sends all balance + msg.value, so balance becomes 0 after both versions if the if-block executes.
        // The difference is: In reference, the if executes when msg.value >= balance, so the condition is true for large msg.value. In bug, the if executes when msg.value <= balance, so true for small msg.value.
        // So after a call to Command (which is only callable by owner), the balance can be anything.
        // I need to find a rule that holds for reference but fails for bug.
        // Let's try: If we call multiplicate with msg.value = 0, in reference the if (0 >= balance) is false (unless balance=0), so nothing happens, balance unchanged. In bug, if (0 <= balance) is true (unless balance=0), so it drains all balance to adr. Therefore, after multiplicate with msg.value=0, the contract balance should be >= initial balance (reference) but in bug it becomes 0.
        vm.deal(address(c), 1 ether);
        initialBalance = address(c).balance;

        // Call multiplicate with 0 value (cannot use msg.value=0 in a payable call, but we can directly call the function)
        // We'll prank as the owner to call multiplicate with 0
        vm.prank(c.Owner());
        (bool multiSuccess,) = address(c).call(abi.encodeWithSignature("multiplicate(address)", adr));
        assertTrue(multiSuccess);

        // Now the rule: The contract balance should be > 0 after this call (reference: if failed, balance unchanged; bug: if succeeded, balance becomes 0)
        assertTrue(address(c).balance > 0);
    }
}

